 }
 catch (ArgumentOutOfRangeException)
 {
     Console.WriteLine("Warning: Test set too small for reliable metrics. Add more data for production use.");
     var trainPredictions = model.Transform(split.TrainSet);
     var trainMetrics = mlContext.BinaryClassification.Evaluate(trainPredictions, labelColumnName: "Label");
     Console.WriteLine($"Train metrics (overfit estimate) — AUC: {trainMetrics.AreaUnderRocCurve:F4}, Accuracy: {trainMetrics.Accuracy:F4}");
 }

 // Save model and register the pooled prediction engine
